using System;
using System.Diagnostics;
using System.IO;

namespace BubbleWallpaperLauncher
{
    internal static class Program
    {
        [STAThread]
        private static void Main()
        {
            string appDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "BubbleWallpaperApp");
            Directory.CreateDirectory(appDir);

            WriteText(appDir, "index.html", @"<!doctype html>
<html lang=""en"">
<head>
  <meta charset=""utf-8"">
  <meta name=""viewport"" content=""width=device-width, initial-scale=1"">
  <title>Bubble Wallpaper</title>
  <meta name=""theme-color"" content=""#071017"">
  <link rel=""manifest"" href=""manifest.webmanifest"">
  <link rel=""icon"" type=""image/png"" href=""bubble-wallpaper-icon.png"">
  <link rel=""apple-touch-icon"" href=""bubble-wallpaper-icon.png"">
  <link rel=""stylesheet"" href=""styles.css"">
</head>
<body>
  <main class=""app-shell"">
    <section class=""wallpaper-stage"" aria-label=""Animated bubble wallpaper"">
      <canvas id=""bubbleCanvas""></canvas>
      <div class=""wallpaper-title"">
        <h1>Bubble Wallpaper</h1>
        <p>Tap bubbles to pop them.</p>
      </div>
    </section>

    <aside class=""controls"" aria-label=""Wallpaper controls"">
      <div class=""control-row"">
        <label for=""palette"">Palette</label>
        <select id=""palette"">
          <option value=""candy"">Candy</option>
          <option value=""lagoon"">Lagoon</option>
          <option value=""sunset"">Sunset</option>
          <option value=""midnight"">Midnight</option>
        </select>
      </div>

      <div class=""control-row"">
        <label for=""density"">Bubbles</label>
        <input id=""density"" type=""range"" min=""12"" max=""52"" value=""28"">
      </div>

      <div class=""control-row"">
        <label for=""speed"">Float Speed</label>
        <input id=""speed"" type=""range"" min=""40"" max=""180"" value=""100"">
      </div>

      <div class=""control-row"">
        <label for=""size"">Bubble Size</label>
        <input id=""size"" type=""range"" min=""60"" max=""180"" value=""112"">
      </div>

      <div class=""button-grid"">
        <button id=""shuffleButton"" type=""button"">Shuffle</button>
        <button id=""soundButton"" type=""button"" aria-pressed=""true"">Sound On</button>
        <button id=""textButton"" type=""button"" aria-pressed=""true"">Text On</button>
        <button id=""downloadButton"" type=""button"">Save PNG</button>
        <button id=""fullscreenButton"" type=""button"">Fullscreen</button>
      </div>
    </aside>
  </main>

  <script src=""app.js""></script>
</body>
</html>
");
            WriteText(appDir, "styles.css", @":root {
  color-scheme: dark;
  font-family: Arial, Helvetica, sans-serif;
  background: #071017;
  color: #f5fbff;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  min-height: 100%;
  margin: 0;
}

body {
  overflow: hidden;
}

button,
select,
input {
  font: inherit;
}

.app-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  width: 100vw;
  height: 100vh;
}

.wallpaper-stage {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: #071017;
}

#bubbleCanvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: pointer;
  touch-action: manipulation;
}

.wallpaper-title {
  position: absolute;
  left: 32px;
  bottom: 28px;
  max-width: min(520px, calc(100% - 64px));
  pointer-events: none;
  text-shadow: 0 2px 22px rgba(0, 0, 0, 0.5);
}

.wallpaper-title h1 {
  margin: 0 0 8px;
  font-size: clamp(38px, 7vw, 92px);
  line-height: 0.9;
  letter-spacing: 0;
}

.wallpaper-title p {
  margin: 0;
  color: rgba(245, 251, 255, 0.78);
  font-size: 18px;
}

.wallpaper-title.is-hidden {
  display: none;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 22px;
  background: #10161b;
  border-left: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: -12px 0 28px rgba(0, 0, 0, 0.22);
  overflow-y: auto;
}

.control-row {
  display: grid;
  gap: 8px;
}

.control-row label {
  color: rgba(245, 251, 255, 0.72);
  font-size: 13px;
}

select {
  width: 100%;
  min-height: 42px;
  padding: 0 12px;
  color: #f5fbff;
  background: #19242b;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 8px;
}

input[type=""range""] {
  width: 100%;
  accent-color: #48c8dc;
}

.button-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: auto;
}

button {
  min-height: 42px;
  color: #f5fbff;
  background: #1d2a32;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 8px;
  cursor: pointer;
}

button:hover {
  background: #263843;
}

button:active {
  transform: translateY(1px);
}

@media (max-width: 760px) {
  body {
    overflow: auto;
  }

  .app-shell {
    grid-template-columns: 1fr;
    grid-template-rows: minmax(0, 1fr) auto;
  }

  .wallpaper-stage {
    min-height: 66vh;
  }

  .wallpaper-title {
    left: 18px;
    bottom: 18px;
    max-width: calc(100% - 36px);
  }

  .wallpaper-title p {
    font-size: 15px;
  }

  .controls {
    border-left: 0;
    border-top: 1px solid rgba(255, 255, 255, 0.12);
    box-shadow: 0 -10px 24px rgba(0, 0, 0, 0.2);
  }
}
");
            WriteText(appDir, "app.js", @"var canvas = document.getElementById(""bubbleCanvas"");
var ctx = canvas.getContext(""2d"");
var paletteSelect = document.getElementById(""palette"");
var densityInput = document.getElementById(""density"");
var speedInput = document.getElementById(""speed"");
var sizeInput = document.getElementById(""size"");
var shuffleButton = document.getElementById(""shuffleButton"");
var soundButton = document.getElementById(""soundButton"");
var textButton = document.getElementById(""textButton"");
var downloadButton = document.getElementById(""downloadButton"");
var fullscreenButton = document.getElementById(""fullscreenButton"");
var wallpaperTitle = document.querySelector("".wallpaper-title"");

var palettes = {
  candy: {
    background: [""#071017"", ""#173040"", ""#281638""],
    bubbles: [""#ee7752"", ""#e73c7e"", ""#23a6d5"", ""#23d5ab"", ""#ffdfd3"", ""#b28dff""]
  },
  lagoon: {
    background: [""#03191d"", ""#063c4a"", ""#102d40""],
    bubbles: [""#7ef9ff"", ""#34d399"", ""#22d3ee"", ""#a7f3d0"", ""#f8fafc""]
  },
  sunset: {
    background: [""#1b1024"", ""#4b1632"", ""#7b2d26""],
    bubbles: [""#fb7185"", ""#f97316"", ""#fde68a"", ""#c084fc"", ""#fdf2f8""]
  },
  midnight: {
    background: [""#020617"", ""#0f172a"", ""#172554""],
    bubbles: [""#93c5fd"", ""#a5b4fc"", ""#67e8f9"", ""#f0f9ff"", ""#c4b5fd""]
  }
};

var bubbles = [];
var particles = [];
var soundEnabled = true;
var textVisible = true;
var lastFrame = 0;
var pixelRatio = 1;

function randomBetween(min, max) {
  return min + Math.random() * (max - min);
}

function currentPalette() {
  return palettes[paletteSelect.value] || palettes.candy;
}

function resizeCanvas() {
  var rect = canvas.getBoundingClientRect();
  pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.max(1, Math.floor(rect.width * pixelRatio));
  canvas.height = Math.max(1, Math.floor(rect.height * pixelRatio));
  ctx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

function makeBubble(resetY) {
  var rect = canvas.getBoundingClientRect();
  var baseSize = Number(sizeInput.value);
  var radius = randomBetween(baseSize * 0.28, baseSize * 0.72);

  return {
    x: randomBetween(-radius, rect.width + radius),
    y: resetY ? rect.height + radius + randomBetween(0, rect.height * 0.65) : randomBetween(-radius, rect.height + radius),
    radius: radius,
    drift: randomBetween(0.55, 1.45),
    phase: randomBetween(0, Math.PI * 2),
    speed: randomBetween(0.25, 0.72),
    alpha: randomBetween(0.38, 0.72),
    color: currentPalette().bubbles[Math.floor(Math.random() * currentPalette().bubbles.length)]
  };
}

function rebuildBubbles() {
  var count = Number(densityInput.value);
  bubbles = [];

  for (var i = 0; i < count; i++) {
    bubbles.push(makeBubble(false));
  }
}

function drawBackground(width, height) {
  var palette = currentPalette();
  var gradient = ctx.createLinearGradient(0, 0, width, height);
  gradient.addColorStop(0, palette.background[0]);
  gradient.addColorStop(0.48, palette.background[1]);
  gradient.addColorStop(1, palette.background[2]);
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);
}

function drawBubble(bubble) {
  var highlightX = bubble.x - bubble.radius * 0.32;
  var highlightY = bubble.y - bubble.radius * 0.36;
  var gradient = ctx.createRadialGradient(highlightX, highlightY, bubble.radius * 0.08, bubble.x, bubble.y, bubble.radius);

  gradient.addColorStop(0, ""rgba(255, 255, 255, 0.96)"");
  gradient.addColorStop(0.18, bubble.color);
  gradient.addColorStop(0.68, ""rgba(255, 255, 255, 0.2)"");
  gradient.addColorStop(1, ""rgba(255, 255, 255, 0.06)"");

  ctx.save();
  ctx.globalAlpha = bubble.alpha;
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(bubble.x, bubble.y, bubble.radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.lineWidth = Math.max(1, bubble.radius * 0.035);
  ctx.strokeStyle = ""rgba(255, 255, 255, 0.42)"";
  ctx.stroke();
  ctx.restore();
}

function drawParticles(delta) {
  for (var i = particles.length - 1; i >= 0; i--) {
    var particle = particles[i];
    particle.life -= delta;
    particle.x += particle.vx * delta * 0.06;
    particle.y += particle.vy * delta * 0.06;

    if (particle.life <= 0) {
      particles.splice(i, 1);
      continue;
    }

    ctx.save();
    ctx.globalAlpha = Math.max(0, particle.life / particle.maxLife);
    ctx.fillStyle = particle.color;
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, particle.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

function frame(time) {
  var rect = canvas.getBoundingClientRect();
  var delta = Math.min(40, time - lastFrame || 16);
  var speedScale = Number(speedInput.value) / 100;

  lastFrame = time;
  drawBackground(rect.width, rect.height);

  for (var i = 0; i < bubbles.length; i++) {
    var bubble = bubbles[i];
    bubble.phase += delta * 0.0014 * bubble.drift;
    bubble.y -= bubble.speed * speedScale * delta * 0.08;
    bubble.x += Math.sin(bubble.phase) * bubble.drift * delta * 0.035;

    if (bubble.y + bubble.radius < -20) {
      bubbles[i] = makeBubble(true);
      bubbles[i].y = rect.height + bubble.radius;
      bubble = bubbles[i];
    }

    drawBubble(bubble);
  }

  drawParticles(delta);
  requestAnimationFrame(frame);
}

function playPopSound() {
  var AudioContext = window.AudioContext || window.webkitAudioContext;

  if (!soundEnabled || !AudioContext) {
    return;
  }

  var audioContext = new AudioContext();
  var now = audioContext.currentTime;
  var oscillator = audioContext.createOscillator();
  var gain = audioContext.createGain();

  oscillator.type = ""sine"";
  oscillator.frequency.setValueAtTime(780, now);
  oscillator.frequency.exponentialRampToValueAtTime(170, now + 0.09);
  gain.gain.setValueAtTime(0.001, now);
  gain.gain.exponentialRampToValueAtTime(0.16, now + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
  oscillator.connect(gain);
  gain.connect(audioContext.destination);
  oscillator.start(now);
  oscillator.stop(now + 0.13);

  window.setTimeout(function () {
    audioContext.close();
  }, 180);
}

function popBubbleAt(x, y) {
  for (var i = bubbles.length - 1; i >= 0; i--) {
    var bubble = bubbles[i];
    var dx = x - bubble.x;
    var dy = y - bubble.y;

    if ((dx * dx) + (dy * dy) <= bubble.radius * bubble.radius) {
      playPopSound();

      for (var p = 0; p < 14; p++) {
        particles.push({
          x: bubble.x + randomBetween(-bubble.radius * 0.2, bubble.radius * 0.2),
          y: bubble.y + randomBetween(-bubble.radius * 0.2, bubble.radius * 0.2),
          vx: randomBetween(-bubble.radius, bubble.radius),
          vy: randomBetween(-bubble.radius, bubble.radius),
          radius: randomBetween(2, 5),
          life: randomBetween(220, 360),
          maxLife: 360,
          color: bubble.color
        });
      }

      bubbles.splice(i, 1);
      bubbles.push(makeBubble(true));
      return;
    }
  }
}

function canvasPoint(event) {
  var rect = canvas.getBoundingClientRect();
  var source = event.touches && event.touches.length ? event.touches[0] : event;

  return {
    x: source.clientX - rect.left,
    y: source.clientY - rect.top
  };
}

function downloadWallpaper() {
  var link = document.createElement(""a"");
  link.download = ""bubble-wallpaper.png"";
  link.href = canvas.toDataURL(""image/png"");
  link.click();
}

canvas.addEventListener(""click"", function (event) {
  var point = canvasPoint(event);
  popBubbleAt(point.x, point.y);
});

canvas.addEventListener(""touchstart"", function (event) {
  var point = canvasPoint(event);
  popBubbleAt(point.x, point.y);
  event.preventDefault();
}, { passive: false });

paletteSelect.addEventListener(""change"", rebuildBubbles);
densityInput.addEventListener(""input"", rebuildBubbles);
sizeInput.addEventListener(""input"", rebuildBubbles);
shuffleButton.addEventListener(""click"", rebuildBubbles);

soundButton.addEventListener(""click"", function () {
  soundEnabled = !soundEnabled;
  soundButton.textContent = soundEnabled ? ""Sound On"" : ""Sound Off"";
  soundButton.setAttribute(""aria-pressed"", String(soundEnabled));
});

textButton.addEventListener(""click"", function () {
  textVisible = !textVisible;
  wallpaperTitle.classList.toggle(""is-hidden"", !textVisible);
  textButton.textContent = textVisible ? ""Text On"" : ""Text Off"";
  textButton.setAttribute(""aria-pressed"", String(textVisible));
});

downloadButton.addEventListener(""click"", downloadWallpaper);

fullscreenButton.addEventListener(""click"", function () {
  var stage = document.querySelector("".wallpaper-stage"");

  if (document.fullscreenElement) {
    document.exitFullscreen();
  } else if (stage.requestFullscreen) {
    stage.requestFullscreen();
  }
});

window.addEventListener(""resize"", function () {
  resizeCanvas();
  rebuildBubbles();
});

resizeCanvas();
rebuildBubbles();
requestAnimationFrame(frame);
");
            WriteText(appDir, "manifest.webmanifest", @"{
  ""name"": ""Bubble Wallpaper"",
  ""short_name"": ""Bubbles"",
  ""description"": ""An interactive bubble wallpaper with tap-to-pop bubbles, sound, palettes, and fullscreen mode."",
  ""start_url"": ""index.html"",
  ""display"": ""standalone"",
  ""background_color"": ""#071017"",
  ""theme_color"": ""#071017"",
  ""icons"": [
    {
      ""src"": ""bubble-wallpaper-icon.png"",
      ""sizes"": ""512x512"",
      ""type"": ""image/png"",
      ""purpose"": ""any maskable""
    }
  ]
}");
            WriteBinary(appDir, "bubble-wallpaper-icon.png", "");

            string appFile = Path.Combine(appDir, "index.html");
            string appUrl = new Uri(appFile).AbsoluteUri;
            string browser = FindBrowser();

            if (!String.IsNullOrEmpty(browser))
            {
                Process.Start(new ProcessStartInfo
                {
                    FileName = browser,
                    Arguments = "--app=\"" + appUrl + "\" --start-fullscreen",
                    UseShellExecute = false
                });
            }
            else
            {
                Process.Start(new ProcessStartInfo
                {
                    FileName = appFile,
                    UseShellExecute = true
                });
            }
        }

        private static void WriteText(string appDir, string fileName, string contents)
        {
            File.WriteAllText(Path.Combine(appDir, fileName), contents);
        }

        private static void WriteBinary(string appDir, string fileName, string base64)
        {
            File.WriteAllBytes(Path.Combine(appDir, fileName), Convert.FromBase64String(base64));
        }

        private static string FindBrowser()
        {
            string[] candidates = new string[]
            {
                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86), "Microsoft", "Edge", "Application", "msedge.exe"),
                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "Microsoft", "Edge", "Application", "msedge.exe"),
                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Microsoft", "Edge", "Application", "msedge.exe"),
                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "Google", "Chrome", "Application", "chrome.exe"),
                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86), "Google", "Chrome", "Application", "chrome.exe"),
                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Google", "Chrome", "Application", "chrome.exe")
            };

            foreach (string candidate in candidates)
            {
                if (File.Exists(candidate))
                {
                    return candidate;
                }
            }

            return null;
        }
    }
}
